# v1: v0 (tune-1 line) plus team-fight style.
# - claim(goal) on every camp goal, so allies can see what we are taking.
# - focus fire: set_team_target on the weakest visible enemy in reach; allies within 6 tiles converge on team_target().
# - ranged champions step away from an adjacent enemy when allies are near (kite), instead of trading in place.
# - camp risk gate: skip a goal when group_threat * group_hp / (1 + allies) exceeds health * CAMP_RISK
#   (CAMP_RISK = 60, tunable); fall back to the next-closest goal.
# - unclaim() before tributing.
# Everything else (draft, spawn shopping, recall, altar logic, ability casting) is unchanged from v0.

# zg14: ability-type-aware casting: shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# walk toward a camp goal: claim it, dash if far, step, attack anything in reach, then end the turn
def go_to(g):
    claim(g)
    if distance(position(), g) > 4:
        dash_to(0, g)
        dash_to(1, g)
    move_towards(g)
    if exists(first(filter(camps_visible(), in_attack_range()))):
        attack(first(filter(camps_visible(), in_attack_range())))
    set_priority(1 + random_int(100))
    end_turn()

