# Team coordination: focus fire on one team_target (weakest visible enemy, re-picked when far or gone),
# ranged kiting away from an adjacent diver when allies are near, regroup toward the nearest ally when
# outnumbered and no enemy is in reach, and rich-camp preference with a walking detour limit.
# Camp choice: a goal is skipped when the damage taken clearing it exceeds our health; the 30 below is a
# stand-in for our own strength, since strength() is not a block.
# Tunable constants (literal numbers, marked below):
#   REGROUP_STRENGTH = 0.8   retreat toward allies below this local_strength(6) with no enemy in reach
#   OWN_STRENGTH     = 30    stand-in for our damage per turn in the camp-cost test
#   RICH_GEMS        = 15    camp groups giving at least this many gems count as rich
#   RICH_DETOUR      = 8     extra walking tiles accepted to reach a rich camp instead of the nearest one
#   KITE_RADIUS      = 4     allies within this radius needed before a ranged champion kites

# ability-type-aware casting: shield/heal on self, dash kept for escape/travel, others at the target
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# walk to a camp goal g; if its clearing cost is too high, walk to the nearest other goal instead
def walk_camp(g, pool):
    if exists(g):
        if group_threat(g) * group_hp(g) / (30 * (1 + allies_within(4))) > health():
            if exists(closest(minus(pool, filter(pool, within(0, g))))):
                claim(closest(minus(pool, filter(pool, within(0, g)))))
                move_towards(closest(minus(pool, filter(pool, within(0, g)))))
                end_turn()
        if distance(position(), g) > 4:
            dash_to(0, g)
            dash_to(1, g)
        claim(g)
        move_towards(g)

