let tf = team_target()
if exists(tf):
    if (distance( unit_position(tf), position() ) <= 1 or (i_am_ranged() and distance( unit_position(tf), position() ) <= 3)) and not contains( enemy_spawn, unit_position(tf) ):
        cast_on(0, tf)
        cast_on(1, tf)
        attack(tf)
        end_turn()
    # chase the team target together with allies when the local fight favours us
    if can_move() and enemies_within(ENGAGE_R) > 0 and allies_within(4) > 0 and local_strength(ENGAGE_R) >= ENGAGE_STR and not contains( enemy_spawn, unit_position(tf) ):
        move_towards( unit_position(tf) )
        end_turn()

