if i_am_ranged() and enemies_within(1) > 0 and can_move():
    move_away_from( unit_position( nearest(enemies_visible()) ) )
    if can_attack():
        let kt = weakest( filter( enemies_visible(), in_attack_range() ) )
        if exists(kt):
            attack(kt)
    end_turn()

# otherwise hit the weakest enemy in reach and make it the team's focus
let foe = weakest( filter( enemies_visible(), in_attack_range() ) )
if exists(foe) and not contains( enemy_spawn, unit_position(foe) ):
    set_team_target(foe)
    cast_on(0, foe)
    cast_on(1, foe)
    attack(foe)
    end_turn()

# regroup: outnumbered nearby with nothing in reach, so walk back toward the nearest ally
let near_ally = nearest( allies_visible() )
if exists(near_ally):
    if enemies_within(ENGAGE_R) > 0 and local_strength(ENGAGE_R) < REGROUP_STR and distance( unit_position(near_ally), position() ) > 2:
        move_towards( unit_position(near_ally) )
        end_turn()

