# and when clearing it is affordable
let joint = closest( minus( claimed_by_allies(), respawning_visible_spawns() ) )
if exists(goal):
    if exists(joint):
        if claim_count(joint) > 0 and distance(position(), joint) <= distance(position(), goal) + JOIN_SLACK and not contains( big_camps, joint ):
            if group_threat(joint) * group_hp(joint) <= health() * MY_DPS * (1 + allies_within(4)) * SKIP_K:
