# v2-team: tune-1 plus team fight coordination.
# - focus fire: name one enemy with set_team_target; champions in reach cast at it and attack it.
# - kiting: a ranged champion with a melee enemy adjacent steps away before it attacks.
# - regroup: outnumbered nearby with nobody in reach, walk toward the nearest ally.
# - camp choice: skip a goal whose clearing cost exceeds what we can absorb, or that already has
#   max_claim allies on it; the next-closest goal is taken instead.
# - claims: every camp goal we walk to is claimed, so allies see and join it.
# Draft, shop, recall, tribute, capture hold, zero-gem monolith fallback and idle fix are kept from v1.

# named constants
keep my_dps = 60
keep max_claim = 3
keep regroup_ratio = 0.8
keep retreat_frac = 0.3
keep gem_retreat_frac = 0.5
keep bag_min = 10
keep dash_min_dist = 4

# ability-type-aware casting: shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# walk to a camp goal, claim it for the team, attack a camp in reach on the way
def camp_go(g):
    if exists(g):
        claim(g)
        if distance(position(), g) > dash_min_dist:
            dash_to(0, g)
            dash_to(1, g)
        move_towards(g)
        if exists(first(filter(camps, in_attack_range()))):
            attack(first(filter(camps, in_attack_range())))
        set_priority( 1 + random_int(100) )

