# Focused change: cut fuel, since team-fight-3 ran out of fuel ~116 turns per game and lost the rest of each such turn:
#  - enemies_visible(), respawning_visible_spawns(), allies_within(4) and camps_visible() are each computed once
#    per turn and reused (go_to takes the camp list as an argument).
#  - the kite and regroup checks only run when an enemy is visible at all, so their costly blocks are skipped otherwise.
#  - spawn_region(ally()) and the static non-goal sets are bound with keep.

# ---- tunable thresholds ----
keep DASH_FAR = 4        # dash toward a camp goal only when farther than this
keep JOIN_SLACK = 3      # extra walking accepted to join an ally-claimed camp group
keep GEM_BAG = 10        # tribute once carrying this many gems
keep REGROUP_STR = 0.8   # regroup toward allies when local strength is below this
keep MY_DPS = 40         # our rough damage per turn, used to estimate the cost of clearing a camp group
keep SKIP_K = 2          # skip a camp group when expected damage taken exceeds health * SKIP_K

keep camp_spawns = camp_spawn_tiles()
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )
keep enemy_spawn = spawn_region(enemy())
keep my_spawn = spawn_region(ally())
keep big_camps = union( monolith_tiles(), golem_tiles() )

# ---- helpers ----
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# walk toward a camp goal, claiming it for allies, attack a camp in reach, then end the turn
def go_to(g, cs):
    claim(g)
    if distance(position(), g) > DASH_FAR:
        dash_to(0, g)
        dash_to(1, g)
    move_towards(g)
    if can_attack():
        let gcamp = first(filter(cs, in_attack_range()))
        if exists(gcamp):
            attack(gcamp)
    set_priority(1 + random_int(100))
    end_turn()

