    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for the attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    end_turn()

# standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let resp = respawning_visible_spawns()

# nothing tributed by round 300: go for monoliths too
if team_score(ally()) == 0 and round_number() > 300:
    move_towards( closest( minus( minus( camp_spawns, resp ), golem_tiles() ) ) )
    end_turn()

let goals = minus( minus( camp_spawns, resp ), big_camps )

let goal = closest(goals)
# on a dead camp of a group not yet cleared: walk to the nearest living camp so the group can be finished
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( big_camps, unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()

