        if not contains( big_camps, joint ):
            if distance(position(), joint) <= distance(position(), goal) + JOIN_SLACK:
                if claim_count(joint) > 0:
                    if group_threat(joint) * group_hp(joint) <= health() * MY_DPS * (1 + aw) * SKIP_K:
