    if group_threat(goal) * group_hp(goal) > health() * MY_DPS * (1 + aw) * SKIP_K:
        let goal2 = closest( minus( goals, filter( goals, within(0, goal) ) ) )
        if exists(goal2):
            go_to(goal2, camps)
    go_to(goal, camps)
end_turn()

