# - claims: goals other allies already claim are joined when not much farther away (join_slack),
#   so champions converge on the same camp group (claimed_by_allies, claim).
# - camp danger: a goal is skipped when group_threat*group_hp/(my_dps*(1+allies)) > health();
#   the next goal is taken, or the champion holds at spawn when every goal is too strong.
# - focus fire: the team names one enemy (set_team_target); every champion that can reach the
#   target attacks and casts at it, otherwise it hits the weakest enemy in reach.
# - regroup: when enemy champions are near and local_strength is below fight_min, the champion
#   pulls back to spawn (where allies gather) instead of walking into the fight.
# - no kiting: ranged champions cannot move and attack in the same turn.
# Draft, shop, recall, tribute, capture hold and the idle fix are kept from tune-1.

# named thresholds
keep retreat_frac = 0.3
keep gem_retreat_frac = 0.5
keep bag_min = 10
keep dash_min_dist = 4
keep my_dps = 60
keep join_slack = 12
keep regroup_r = 6
keep fight_min = 0.8

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

def too_dangerous(g, n):
    return group_threat(g) * group_hp(g) / (my_dps * (1 + n)) > health()

def go_to(g, cs):
    if exists(g):
        claim(g)
        if distance(position(), g) > dash_min_dist:
            dash_to(0, g)
            dash_to(1, g)
    move_towards(g)
    if exists(first(filter(cs, in_attack_range()))):
        attack(first(filter(cs, in_attack_range())))
    set_priority( 1 + random_int(100) )
    end_turn()

def walk_goal(g, gs, cs, n):
    if too_dangerous(g, n):
        let alt = closest( minus( gs, filter( gs, within(0, g) ) ) )
        if exists(alt) and not too_dangerous(alt, n):
            go_to(alt, cs)
        else:
            # every nearby goal is too strong for the group: hold at spawn
            move_towards( closest( spawn_region(ally()) ) )
            end_turn()
    else:
        go_to(g, cs)

