# ---- focus fire: one shared target, the weakest visible enemy when the old one is far or gone ----
let vis_weak = weakest( enemies_visible() )
if exists(vis_weak) and distance(unit_position(team_target()), position()) > focus_r:
    set_team_target(vis_weak)

let focus = team_target()
let focus_d = distance( unit_position(focus), position() )
let focus_reach = focus_d <= 1 or (i_am_ranged() and focus_d <= 3)
# an enemy on its own spawn is healed every turn: fighting it there never ends
let focus_live = exists(focus) and not contains( spawn_region(enemy()), unit_position(focus) )
if focus_live and focus_reach:
    cast_on(0, focus)
    cast_on(1, focus)
    attack(focus)
    end_turn()

# anything else in attack range: hit the weakest
let foe = weakest( filter( enemies_visible(), in_attack_range() ) )
if exists(foe) and not contains( spawn_region(enemy()), unit_position(foe) ):
    cast_on(0, foe)
    cast_on(1, foe)
    attack(foe)
    end_turn()

# ---- engage: the focus target is near and the local fight favours us, so close in with the group ----
if focus_live and focus_d <= focus_r and can_move() and local_strength(focus_r) >= engage_ratio:
    move_towards( unit_position(focus) )
    end_turn()

# ---- regroup: outnumbered and nothing in reach, so walk back toward the nearest ally ----
let buddy = nearest( allies_visible() )
if enemies_within(8) > 0 and local_strength(8) < regroup_ratio and exists(buddy) and distance(unit_position(buddy), position()) > 2 and can_move():
    move_towards( unit_position(buddy) )
    end_turn()

# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 10 or round_number() > 1500 or health() < 0.5 * max_health()
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock (5 hits clear it)
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach (5); else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp: fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    end_turn()

# nothing tributed by round 300: go for monoliths too
if team_score(ally()) == 0 and round_number() > 300:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

let goal = closest(goals)
# on a dead camp of an uncleared group: walk to the nearest living camp so the group can be finished
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()

# camp danger: skip a group we cannot clear, counting allies near us and allies already committed to it
if exists(goal) and distance(goal, position()) > 0:
    if group_threat(goal) * group_hp(goal) / (my_dps * (1 + allies_within(ally_r) + claim_count(goal))) > health():
        let goal_b = closest( minus( goals, filter(goals, within(0, goal)) ) )
        if exists(goal_b):
            claim(goal_b)
            move_towards(goal_b)
            end_turn()

# tunable: dash toward a camp goal only when it is farther than 4
if exists(goal) and distance(position(), goal) > 4:
    dash_to(0, goal)
    dash_to(1, goal)
if exists(goal):
    claim(goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# v2-team [team-fight line]: parent tune-1 (v1). Its draft, shopping, retreat, tribute and farming rules are unchanged.
# Changes vs the parent:
#  - focus fire: the weakest enemy in reach is named with set_team_target, and every champion that can reach it
#    casts its abilities and attacks it;
#  - kiting: a ranged champion with a melee enemy adjacent and an ally nearby steps away first (if it can move);
#  - team pull: a healthy champion with an ally nearby walks toward the team target when it is within 4 tiles;
#  - camp choice: a camp group whose damage taken while clearing exceeds our health is skipped for the closest
#    safe group (group_threat / group_hp / allies_within), and the goal is claimed so allies can see it and join.
# Tunable constants: my_dps = 60 (our damage per turn), 4 = ally radius for kiting and pulls, 4 = team-pull range,
# 0.6 = health needed to pull toward the team target.

# zg14: ability-type-aware casting from hybrid #14 (Opus): shield/heal on self, dash kept for escape/travel
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )
keep my_dps = 60

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 3 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat at 30% health when something can hit us; otherwise recall once clear
if not at_spawn and health() < 0.3 * max_health():
    if in_danger():
        let home = closest( spawn_region(ally()) )
        dash_to(0, home)
        dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
# carrying gems and hurt: head home to tribute once nothing can hit us
if not at_spawn and gems() > 0 and health() < 0.5 * max_health() and not in_danger():
    recall()
    end_turn()

# ---- fighting: focus fire on the weakest enemy in reach ----
let focus = weakest( filter( enemies_visible(), in_attack_range() ) )
# an enemy on its own spawn is healed every turn: fighting it there never ends
if exists(focus) and not contains( spawn_region(enemy()), unit_position(focus) ):
    # name the focus so allies who can see it converge on it
    set_team_target(focus)
    # kite: a ranged champion with a melee enemy adjacent and an ally nearby steps back first
    if i_am_ranged() and can_move() and enemies_within(1) > 0 and allies_within(4) > 0:
        move_away_from( unit_position( nearest(enemies_visible()) ) )
        end_turn()
    cast_on(0, focus)
    cast_on(1, focus)
    attack(focus)
    end_turn()

# ---- tribute ----
# tribute only with a worthwhile bag (or when hurt / late game)
let bag_ready = gems() >= 10 or round_number() > 1500 or health() < 0.5 * max_health()
if gems() > 0 and bag_ready:
    # an altar next to us works even when locked: tributing there attacks the lock (5 hits clear it)
    let altar = first( filter( altars(), within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # walk to an open altar out of monolith reach (5); else any altar out of reach; else any altar
    let target = closest( minus( safe_altar_ring, ring(locked_altars(), 1) ) )
    if exists(target):
        move_towards(target)
        end_turn()
    let target2 = closest(safe_altar_ring)
    if exists(target2):
        move_towards(target2)
        end_turn()
    let altar_goal = closest(altar_ring)
    # every altar-adjacent tile is taken by a camp: fight it
    if contains(camp_spawns, altar_goal):
        let blocker = first( filter( camps_visible(), in_attack_range() ) )
        if exists(blocker):
            attack(blocker)
            end_turn()
    move_towards( altar_goal )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    cast_on(0, camp)
    cast_on(1, camp)
    attack(camp)
    end_turn()

# ---- team pull: walk toward a nearby team target when healthy and backed by an ally ----
let tt = team_target()
if exists(tt) and health() >= 0.6 * max_health() and allies_within(4) > 0 and distance(unit_position(tt), position()) <= 4:
    if not contains( spawn_region(enemy()), unit_position(tt) ):
        move_towards( unit_position(tt) )
        end_turn()

# nothing tributed by round 300 (00contest: only monoliths carry gems): go for monoliths too
if team_score(ally()) == 0 and round_number() > 300:
    move_towards( closest( minus( minus( camp_spawns, respawning_visible_spawns() ), golem_tiles() ) ) )
    end_turn()
let goals = minus( minus( minus( camp_spawns, respawning_visible_spawns() ), monolith_tiles() ), golem_tiles() )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(capturable_spawns(), position()):
    end_turn()

# camp choice: if the closest group costs more health to clear than we have, go to the closest group
# outside it instead (one step of avoidance; the check is redone every turn)
let goal0 = closest(goals)
let risky = exists(goal0) and group_threat(goal0) * group_hp(goal0) / (my_dps * (1 + allies_within(4))) > health()
if risky and distance(goal0, position()) > 0:
    let safer = closest( minus( goals, group_tiles(goal0) ) )
    if exists(safer):
        move_towards(safer)
        end_turn()

let goal = closest(goals)
# on a dead camp of a group that is not cleared yet, walk to the nearest living camp instead
if distance(goal, position()) == 0:
    let live = nearest(camps)
    if exists(live) and not contains( union( monolith_tiles(), golem_tiles() ), unit_position(live) ):
        move_towards( unit_position(live) )
        end_turn()

# commit to this camp so allies can see it and join
if exists(goal):
    claim(goal)

# dash toward a far camp goal only when it is farther than 4
if exists(goal) and distance(position(), goal) > 4:
    dash_to(0, goal)
    dash_to(1, goal)
move_towards( goal )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# v9-teamfight: v8-team (tune-1 farming core) plus group fighting and camp danger checks.
# - focus fire kept: the team names one target, every champion in reach casts at it and attacks it.
# - converge: with no enemy in reach, a healthy champion with an ally nearby walks to the team
#   target when it is close and our numbers there are at least even.
# - kite: a hurt ranged champion with an enemy adjacent casts its abilities at it and steps away.
# - camp danger: skip the closest goal when clearing it would cost more health than we have
#   (group_threat * group_hp / (my_dps * (1 + allies nearby)) > health) and another goal exists.
# - claims: every camp goal we walk to is claimed.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

def go_goal(g, cs):
    if exists(g):
        claim(g)
        if distance(position(), g) > dash_min_dist:
            dash_to(0, g)
            dash_to(1, g)
    move_towards(g)
    let camp2 = first( filter( cs, in_attack_range() ) )
    if exists(camp2):
        attack(camp2)
    set_priority( 1 + random_int(100) )
    end_turn()

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep altar_ring = ring( altars(), 1 )
keep safe_altar_ring = ring( minus( altars(), ring(monolith_tiles(), 5) ), 1 )
# named thresholds
keep retreat_frac = 0.3
keep gem_retreat_frac = 0.5
keep bag_min = 10
keep dash_min_dist = 4
keep my_dps = 60
keep kite_frac = 0.6
keep converge_frac = 0.6
keep converge_range = 6

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let treasure_n = floor( shards_bought / 2 )
    let rest_after_treasure = shards_bought - treasure_n
    let jungle_n = floor( rest_after_treasure / 3 )
    let rest_after_jungle = rest_after_treasure - jungle_n
    let strength_shards = floor( rest_after_jungle / 2 )
    buy( shard_of(family_treasure(), stat_strength()), treasure_n )
    buy( shard_of(family_jungle(), stat_health()), jungle_n )
    buy( shard(stat_strength()), strength_shards )
    buy( shard(stat_health()), rest_after_jungle - strength_shards )
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

if not at_spawn and health() < retreat_frac * max_health():
    if in_danger():
        let home = closest( spawn_region(ally()) )
        dash_to(0, home)
        dash_to(1, home)
        move_towards(home)
        end_turn()
    recall()
    end_turn()
if not at_spawn and gems() > 0 and health() < gem_retreat_frac * max_health() and not in_danger():
    recall()
    end_turn()

let enemy = weakest( filter( enemies_visible(), in_attack_range() ) )
if exists(enemy) and not contains( spawn_region(enemy()), unit_position(enemy) ):
    # kite: hurt ranged champion with an enemy adjacent casts and steps away
    if i_am_ranged() and can_move() and health() < kite_frac * max_health():
        let close_enemy = nearest( enemies_visible() )
        if exists(close_enemy) and distance( unit_position(close_enemy), position() ) <= 1:
            cast_on(0, close_enemy)
            cast_on(1, close_enemy)
            move_away_from( unit_position(close_enemy) )
            end_turn()
    if not exists(team_target()):
        set_team_target(enemy)
    let tt = team_target()
    if exists(tt) and not contains( spawn_region(enemy()), unit_position(tt) ):
        let tt_reach = distance( unit_position(tt), position() )
        if tt_reach <= 1 or (i_am_ranged() and tt_reach <= 3):
            cast_on(0, tt)
            cast_on(1, tt)
            attack(tt)
            if can_attack():
                attack(enemy)
            end_turn()
    cast_on(0, enemy)
    cast_on(1, enemy)
    attack(enemy)
    end_turn()

let bag_ready = gems() >= bag_min or round_number() > 1500 or health() < 0.5 * max_health()
if gems() > 0 and bag_ready:
    let altar = first( filter( altars(), within(1, position()) ) )
